from PIL import Image
from rcb_client import Robot
DT=.02; PERIOD=1.; FIRST=150; N=350
r=Robot(); spec=r.spec(); st=r.status(); print('before',json.dumps(st))
ranges=np.asarray(spec['action_types']['joint_position']['range_rad'],dtype=np.float32)
def norm(q): return np.clip(2*(np.asarray(q)-ranges[:,0])/(ranges[:,1]-ranges[:,0])-1,-1,1)
